import { userSchemaValidation } from "../Validations/UserValidations";
import { companySchemaValidation } from "../Validations/CompanyValidation";
import * as yup from "yup";
import { useForm } from "react-hook-form";
import { useState } from "react";
import { yupResolver } from "@hookform/resolvers/yup";
import { Button, Col, Container, Row, Form } from "reactstrap";
import { Link, useNavigate } from "react-router-dom";
import "../Styles/StudentRegister.css";

const StudentRegister = () => {
  const [role, setRole] = useState("Student");
  const navigate = useNavigate();

  // State variables
  const [name, setname] = useState("");
  const [email, setemail] = useState("");
  const [password, setpassword] = useState("");
  const [confirmPassword, setconfirmPassword] = useState("");

  const [companyName, setCompanyName] = useState("");
  const [industry, setIndustry] = useState("");
  const [location, setLocation] = useState("");

  // form validation: switch schema based on role
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(
      role === "Student" ? userSchemaValidation : companySchemaValidation
    ),
  });

  const onSubmit = async (data) => {
    try {
      const res = await fetch("http://localhost:3001/studentregister", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ role, ...data }),
      });

      const result = await res.json();

      if (res.status !== 201) {
        alert(result.message || "Registration failed.");
        return;
      }

      alert("Account created successfully!");
      navigate("/studentlogin");
    } catch (e) {
      console.log(e);
      alert("Server error, try again later.");
    }
  };

  return (
    <Container fluid className="register-container">
      <div className="register-box">
        <h2>
          Create your <span>account</span>
        </h2>

        <p className="choose-role">
          Please choose your role to continue and fill in the following:
        </p>

        {/* Role Buttons */}
        <div className="role-buttons">
          <button
            type="button"
            className={role === "Student" ? "active" : ""}
            onClick={() => setRole("Student")}
          >
            Student
          </button>
          <button
            type="button"
            className={role === "Company" ? "active" : ""}
            onClick={() => setRole("Company")}
          >
            Company
          </button>
        </div>

        {/* Form */}
        <Form className="div-form" onSubmit={handleSubmit(onSubmit)}>
          {role === "Student" ? (
            <>
              <Row>
                <Col md={12}>
                  <label className="input-label">Full Name</label>
                  <input
                    type="text"
                    placeholder="Enter your name"
                    {...register("name", {
                      value: name,
                      onChange: (e) => setname(e.target.value),
                    })}
                  />
                  <p className="error">{errors.name?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <label className="input-label">Email</label>
                  <input
                    type="email"
                    placeholder="you@example.com"
                    {...register("email", {
                      value: email,
                      onChange: (e) => setemail(e.target.value),
                    })}
                  />
                  <p className="error">{errors.email?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <label className="input-label">Password</label>
                  <input
                    type="password"
                    placeholder="Enter your password"
                    {...register("password", {
                      value: password,
                      onChange: (e) => setpassword(e.target.value),
                    })}
                  />
                  <p className="error">{errors.password?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <label className="input-label">Confirm Password</label>
                  <input
                    type="password"
                    placeholder="Confirm your password"
                    {...register("confirmPassword", {
                      value: confirmPassword,
                      onChange: (e) => setconfirmPassword(e.target.value),
                    })}
                  />
                  <p className="error">{errors.confirmPassword?.message}</p>
                </Col>
              </Row>
            </>
          ) : (
            <>
              <Row>
                <Col md={6}>
                  <label className="input-label">Company Name</label>
                  <input
                    type="text"
                    placeholder="Enter company name"
                    {...register("companyName", {
                      value: companyName,
                      onChange: (e) => setCompanyName(e.target.value),
                    })}
                  />
                  <p className="error">{errors.companyName?.message}</p>
                </Col>

                <Col md={6}>
                  <label className="input-label">Email</label>
                  <input
                    type="email"
                    placeholder="you@example.com"
                    {...register("email", {
                      value: email,
                      onChange: (e) => setemail(e.target.value),
                    })}
                  />
                  <p className="error">{errors.email?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={6}>
                  <label className="input-label">Password</label>
                  <input
                    type="password"
                    placeholder="Enter password"
                    {...register("password", {
                      value: password,
                      onChange: (e) => setpassword(e.target.value),
                    })}
                  />
                  <p className="error">{errors.password?.message}</p>
                </Col>

                <Col md={6}>
                  <label className="input-label">Industry Type</label>
                  <select
                    {...register("industry", {
                      value: industry,
                      onChange: (e) => setIndustry(e.target.value),
                    })}
                  >
                    <option value="">Select industry</option>
                    <option value="Education">Education</option>
                    <option value="Technology">Technology</option>
                    <option value="Business">Business</option>
                    <option value="Health">Health</option>
                    <option value="Other">Other</option>
                  </select>
                  <p className="error">{errors.industry?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <label className="input-label">Location</label>
                  <select
                    {...register("location", {
                      value: location,
                      onChange: (e) => setLocation(e.target.value),
                    })}
                  >
                    <option value="">Select location</option>
                    <option value="Salalah">Salalah</option>
                    <option value="Mirbat">Mirbat</option>
                    <option value="Thamreet">Thamreet</option>
                    <option value="Taqa">Taqa</option>
                    <option value="Hasik">Hasik</option>
                  </select>
                  <p className="error">{errors.location?.message}</p>
                </Col>
              </Row>
            </>
          )}

          <Row>
            <Col md={12}>
              <Button className="signup-btn" type="submit">
                Sign Up
              </Button>
            </Col>
          </Row>

          <p className="login-link">
            Already have an account? <Link to="/studentlogin">Log in now!</Link>
          </p>
        </Form>
      </div>
    </Container>
  );
};

export default StudentRegister;
